using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;using EchoSphere.Core;using EchoSphere.Presentation;
public static class ArchiveIllustrationUiCheck {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 public static object Main()=>Run(false); public static object Character()=>Run(true); private static object Run(bool character){if(!Application.isPlaying)throw new Exception("Play required");var owner=new GameObject("Owned archive illustration smoke");var screen=owner.AddComponent<NativeArchiveScreen>();var entry=BestiaryCatalog.All[0];var monster=new NativeArchiveScreen.Card{Id=entry.Id,Open=true,Enemy=entry.DefaultAppearance(),Title=entry.NameRu,Description=BestiaryCatalog.Behavior(0,"grunt",true),Details=entry.LoreRu};var person=CharacterRules.All.Single(c=>CharacterRules.ToSourceId(c.Id)=="hunter");var avatar=new NativeArchiveScreen.Card{Id="character:hunter",CharacterId="hunter",Open=true,Title=person.NameEn,Description=person.DescriptionEn,Details=ArchiveLore.Character("hunter").En};var card=character?avatar:monster;var other=character?monster:avatar;screen.Show(new NativeArchiveScreen.State{Russian=!character,Section=character?"characters":"monsters",Query="",Cards=new[]{card},Known=1},1,()=>{},_=>{},_=>{});
 var root=(VisualElement)typeof(NativeArchiveScreen).GetField("_root",F).GetValue(screen);root.style.width=420;root.style.height=850;var panel=(PanelSettings)typeof(NativeArchiveScreen).GetField("_panel",F).GetValue(screen);var target=new RenderTexture(420,850,0);target.Create();panel.targetTexture=target;
 var open=typeof(NativeArchiveScreen).GetMethod("OpenDetail",F);var close=typeof(NativeArchiveScreen).GetMethod("CloseDetail",F);for(int i=0;i<20;i++){open.Invoke(screen,new object[]{i%2==0?card:other});close.Invoke(screen,null);}open.Invoke(screen,new object[]{card});
 int frames=0;double deadline=EditorApplication.timeSinceStartup+45;EditorApplication.CallbackFunction tick=null;
 void Finish(string status,string error=null){EditorApplication.update-=tick;screen.Hide();panel.targetTexture=null;UnityEngine.Object.DestroyImmediate(owner);target.Release();UnityEngine.Object.DestroyImmediate(target);File.WriteAllText("Library/archive-illustrations/"+(character?"ui-character.json":"ui-acceptance.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{status,error,frames,scope="attached mobile-width detail, asynchronous picture, 20 rapid pending switches A/B/A, current-entry identity, locked guard, GPU screenshot; isolated UI, no player save modifications"}));}
 Application.runInBackground=true;tick=()=>{try{EditorApplication.QueuePlayerLoopUpdate();frames++;if(EditorApplication.timeSinceStartup>deadline){Finish("FAIL","deadline");return;}var image=root.Q<Image>("archive-detail-illustration");if(image?.image==null||frames<15)return;if(image.image.name!=card.Id.Replace(':','-'))throw new Exception("stale picture from another entry");var box=root.Q("archive-detail-art");if(box.worldBound.width>420||Math.Abs(box.worldBound.height-box.worldBound.width*2/3)>2)throw new Exception("illustration aspect/bounds");foreach(var label in root.Q("archive-entry-detail").Query<Label>().ToList())if(label.worldBound.xMax>421)throw new Exception("horizontal overflow "+label.name);var old=RenderTexture.active;var shot=new Texture2D(420,850,TextureFormat.RGB24,false);try{RenderTexture.active=target;shot.ReadPixels(new Rect(0,0,420,850),0,0);shot.Apply();File.WriteAllBytes("Library/archive-illustrations/"+(character?"detail-character.png":"detail-realistic.png"),shot.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(shot);}close.Invoke(screen,null);if(root.Q("archive-entry-detail")!=null)throw new Exception("detail removal");var locked=new NativeArchiveScreen.Card{Id=entry.Id,Open=false,Enemy=entry.DefaultAppearance()};open.Invoke(screen,new object[]{locked});if(root.Q("archive-entry-detail")!=null)throw new Exception("locked entry opens artwork");Finish("PASS");}catch(Exception e){Finish("FAIL",e.ToString());}};EditorApplication.update+=tick;return new{status="queued"};
 }
}
